          `${ARCHIVE_URL}?${p.qs}&start_date=${startStr}&end_date=${endStr}&daily=temperature_2m_mean,pressure_msl_mean,wind_speed_10m_mean,wind_direction_10m_dominant,cloud_cover_mean&wind_speed_unit=kmh`,
