    });
    throw e;
  }
}

export function hourlyIndexAt(times: string[], iso: string): number {
  const t = new Date(iso).getTime();
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < times.length; i++) {
    const d = Math.abs(new Date(times[i]).getTime() - t);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

export function numAt(arr: (number | null)[] | undefined, i: number): number | null {
  if (!arr || i < 0 || i >= arr.length) return null;
  const v = arr[i];
  return v == null || Number.isNaN(v) ? null : v;
}

export function hoursAgoIndex(times: string[], fromIso: string, hours: number): number {
  const target = new Date(fromIso).getTime() - hours * 3600_000;
  return hourlyIndexAt(times, new Date(target).toISOString());
}

export function archiveToClimate(archive: OpenMeteoArchive): DailyClimate[] {
  const t = archive.daily.time;
  const out: DailyClimate[] = [];
  for (let i = 0; i < t.length; i++) {
    const p = archive.daily.pressure_msl_mean[i];
    const prev = i > 0 ? archive.daily.pressure_msl_mean[i - 1] : null;
    out.push({
      date: t[i],
      airTempC: archive.daily.temperature_2m_mean[i],
      pressureHpa: p,
      pressureDelta: p != null && prev != null ? Number((p - prev).toFixed(2)) : null,
      windKmh: archive.daily.wind_speed_10m_mean[i],
      windDirDeg: archive.daily.wind_direction_10m_dominant[i],
      cloudPct: archive.daily.cloud_cover_mean[i],
    });
  }
  return out;
}

export function mean(values: (number | null)[]): number | null {
  const xs = values.filter((v): v is number => v != null && !Number.isNaN(v));
  if (!xs.length) return null;
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

export function todayKey(): string {
  return parisDateKey(new Date());
}

import type { QualityLevel } from "./types";
import { minutesAgo } from "./format";

export function freshnessQuality(fetchedAt: string | null, stale: boolean): QualityLevel {
  if (!fetchedAt) return 1;
  const m = minutesAgo(fetchedAt) ?? 9999;
  if (stale || m > 180) return 2;
  if (m > 60) return 3;
  if (m > 25) return 4;
  return 5;
}

export function waterQuality(kind: "mesure" | "estimation", hasRecentMeasure: boolean): QualityLevel {
  if (kind === "mesure" && hasRecentMeasure) return 5;
  if (kind === "mesure") return 4;
  return 3;
}

export function historicalQuality(analogCount: number, archiveDays: number): QualityLevel {
  if (archiveDays < 30) return 2;
  if (analogCount >= 20 && archiveDays >= 365) return 5;
  if (analogCount >= 8) return 4;
  if (analogCount >= 3) return 3;
  return 2;
}

export function combineConfidence(parts: {
  weatherFresh: QualityLevel;
  water: QualityLevel;
  historical: QualityLevel;
  completeness: number;
}): number {
  const q = (parts.weatherFresh + parts.water + parts.historical) / 15;
  const complete = Math.max(0, Math.min(1, parts.completeness));
  return Math.round(100 * (0.55 * q + 0.45 * complete));
}

import { LAKE, sectorById } from "../lake";
import { getConfig } from "../config";
import { listCatches } from "../store/catches";
